use serde_json::json;
#[test]fn busy_host_selection_is_committed_before_next_actual_model_request(){let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");std::fs::write(&cfg,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let mut lp=hs_loop::InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),d.path(),false,1).unwrap();lp.set_plan_guidance("Guide".into()).unwrap();let inbox=d.path().join("plan-input");lp.set_plan_inbox(&inbox);std::fs::write(&inbox,json!({"stream_id":lp.stream_id(),"active":true}).to_string()+"\n").unwrap();lp.run_mission("selected").unwrap();assert_eq!(lp.plan_view()["active"],true);assert_eq!(std::fs::read_to_string(&inbox).unwrap(),"");let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let vals:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert!(vals.iter().filter_map(|v|v["messages"].as_array()).any(|ms|ms.iter().any(|m|m["content"]=="Guide")));}
#[test]fn stale_other_session_selection_and_malformed_fields_fail_closed(){let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");std::fs::write(&cfg,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let mut lp=hs_loop::InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),d.path(),false,1).unwrap();lp.set_plan_guidance("Guide".into()).unwrap();let inbox=d.path().join("plan-input");lp.set_plan_inbox(&inbox);std::fs::write(&inbox,format!("{}\n{}\n",json!({"stream_id":uuid::Uuid::new_v4(),"active":true}),json!({"stream_id":lp.stream_id(),"active":"true"}))).unwrap();lp.run_mission("notselected").unwrap();assert_eq!(lp.plan_view()["active"],false);}
#[test]fn multiple_host_selections_use_final_choice_and_preserve_sourced_message(){let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");std::fs::write(&cfg,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let mut lp=hs_loop::InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),d.path(),false,1).unwrap();lp.set_plan_guidance("Guide".into()).unwrap();let inbox=d.path().join("plan-input");lp.set_plan_inbox(&inbox);for (active,message) in [(true,Some("Preserve original request")),(false,None)]{hs_loop::dshplan::append_selection(&inbox,&json!({"stream_id":lp.stream_id(),"active":active,"message":message})).unwrap();}lp.run_mission("finalchoice").unwrap();assert_eq!(lp.plan_view()["active"],false);let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let vals:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert!(vals.iter().filter_map(|v|v["messages"].as_array()).any(|m|m.iter().any(|m|m["content"]=="Preserve original request")));}
#[test]fn concurrent_host_append_and_drain_lose_no_input(){let d=tempfile::tempdir().unwrap();let path=d.path().join("inbox");let p=path.clone();let w=std::thread::spawn(move||{for i in 0..100{hs_loop::dshplan::append_selection(&p,&json!({"i":i})).unwrap();}});let mut all=vec![];while !w.is_finished(){all.extend(hs_loop::dshplan::take_selections(&path).unwrap());}w.join().unwrap();all.extend(hs_loop::dshplan::take_selections(&path).unwrap());let mut ids:Vec<_>=all.iter().map(|v|v["i"].as_i64().unwrap()).collect();ids.sort();assert_eq!(ids,(0..100).collect::<Vec<_>>());}
